import { useEffect, useLayoutEffect, useRef, useState } from 'react';
import { Board } from '../board/Board.tsx';
import { GameStatus } from '../status/GameStatus.tsx';
import { browserStore } from '../session/use-saved-preferences.ts';
import { useTournament } from '../session/use-tournament.ts';
import { Bracket } from './Bracket.tsx';
import { Exchange } from './Exchange.tsx';
import { LeaveDialog } from './LeaveDialog.tsx';
import { Setup } from './Setup.tsx';
import { encodeTournament, decodeTournament } from './format.ts';
import { readTournaments, saveTournament } from './history.ts';
import { matchPlayers, matchWinner, roundFor } from './rules.ts';
import { TournamentPhase } from './model.ts';
import type { BoardFocus } from '../board/Board.tsx';
import type { TournamentState } from './model.ts';
import './tournament.css';

interface TournamentProps {
  back(): void;
  publish(message: string): void;
}

export function Tournament({ back, publish }: TournamentProps) {
  const controller = useTournament();
  const { tournament: state, session } = controller;
  const [names, setNames] = useState<readonly string[]>(['', '', '', '']);
  const [error, setError] = useState('');
  const [store] = useState(browserStore);
  const [history, setHistory] = useState(() => readTournaments(store));
  const [pending, setPending] = useState<(() => void) | null>(null);
  const heading = useRef<HTMLHeadingElement>(null);
  const board = useRef<BoardFocus>(null);
  const saved = useRef<TournamentState | null>(null);
  const phase = state?.phase;
  const matchIndex = state?.matchIndex;
  const turn = state?.turn;
  useLayoutEffect(() => { heading.current?.focus(); }, [phase, matchIndex, turn, session.generation]);
  useEffect(() => { publish(session.feedback); }, [publish, session.feedback, session.announcement]);
  useEffect(() => {
    if (state?.phase !== TournamentPhase.complete || saved.current === state) return;
    saved.current = state;
    setHistory((previous) => saveTournament(store, previous.items, state));
  }, [state, store]);

  function report(message: string): void { setError(message); publish(message); }
  function replace(action: () => void): void {
    if (state && state.phase !== TournamentPhase.complete) setPending(() => action);
    else action();
  }
  function load(text: string): void {
    const decoded = decodeTournament(text);
    const document = decoded.document;
    if (!document) { report(decoded.error); return; }
    replace(() => {
      setError('');
      if (document.setup) setNames(document.setup);
      controller.install(document.tournament);
      publish('Loaded tournament.');
    });
  }

  const seeds = state ? matchPlayers(state, state.matchIndex) : null;
  const player = state && seeds ? state.players[(seeds[state.turn] ?? 1) - 1] : '';
  const champion = state ? matchWinner(state, state.matches.length - 1) : null;
  return (
    <section className="tournament-screen" aria-labelledby="tournament-heading">
      <h2 ref={heading} id="tournament-heading" tabIndex={-1}>Tournament</h2>
      {!state ? <>
        <Setup names={names} change={setNames} error={error} publish={report}
          start={(players) => { setError(''); controller.start(players); }} />
        <section className="past-tournaments" aria-labelledby="past-heading">
          <h3 id="past-heading">Past tournaments</h3>
          {history.blocked && <p>Progress won't be saved on this device.</p>}
          {history.items.length === 0 ? <p>No finished tournaments yet.</p> : <ol>
            {history.items.map((item, index) => <li key={index}>
              <button type="button" className="control" onClick={() => controller.install(item)}>
                {item.players.length} players · Champion: {item.players[(matchWinner(item, item.matches.length - 1) ?? 1) - 1]}
              </button>
            </li>)}
          </ol>}
        </section>
        <button type="button" className="control" onClick={back}>Back to game</button>
      </> : <>
        {phase === TournamentPhase.complete ? <>
          <p className="tournament-champion">Champion: {state.players[(champion ?? 1) - 1]}</p>
          <div className="tournament-actions">
            <button type="button" className="control" onClick={back}>Back to game</button>
            <button type="button" className="control" onClick={() => controller.install(null)}>Past tournaments</button>
          </div>
        </> : <>
          <p>Round: {roundFor(state.players.length, state.matchIndex).name}</p>
          <p>Match {state.matchIndex + 1} of {state.matches.length}</p>
          <p className="tournament-player">Now playing: {player}</p>
          <div className="tournament-actions">
            {(phase === TournamentPhase.ready || (phase === TournamentPhase.playing && session.paused)) &&
              <button type="button" className="control" onClick={controller.startTurn}>Start turn</button>}
            {phase === TournamentPhase.turnFinished &&
              <button type="button" className="control" onClick={controller.nextTurn}>Next turn</button>}
            {phase === TournamentPhase.matchFinished &&
              <button type="button" className="control" onClick={controller.nextTurn}>Next match</button>}
            <button type="button" className="control" onClick={() => replace(back)}>Leave tournament</button>
          </div>
          {phase !== TournamentPhase.ready && <>
            <GameStatus game={state.game} best={undefined} celebration={session.celebration} />
            <p id="board-help" className="help">Arrow keys move between cards. Enter or Space reveals a card.</p>
            <Board key={session.generation} ref={board} game={state.game} activate={controller.activate} />
          </>}
        </>}
        <Bracket tournament={state} />
        {history.blocked && <p>Progress won't be saved on this device.</p>}
      </>}
      <Exchange exportTournament={() => encodeTournament({
        setup: state ? null : names, tournament: controller.synchronizedTournament(),
      })} load={load} />
      {state && error && <p>{error}</p>}
      {pending && <LeaveDialog keepPlaying={() => setPending(null)} leave={() => {
        setPending(null); pending();
      }} />}
    </section>
  );
}

