              <div className="tournament-actions">
                <button type="button" className="control" onClick={back}>
                  Back to game
                </button>
                <button type="button" className="control" onClick={() => controller.install(null)}>
                  Past tournaments
                </button>
              </div>
            </>
          ) : (
