              </p>
              <p className="tournament-player">Now playing: {player}</p>
              <div className="tournament-actions">
                {(phase === TournamentPhase.ready ||
                  (phase === TournamentPhase.playing && session.paused)) && (
                  <button type="button" className="control" onClick={controller.startTurn}>
                    Start turn
                  </button>
                )}
                {phase === TournamentPhase.turnFinished && (
                  <button type="button" className="control" onClick={controller.nextTurn}>
                    Next turn
                  </button>
                )}
                {phase === TournamentPhase.matchFinished && (
                  <button type="button" className="control" onClick={controller.nextTurn}>
                    Next match
                  </button>
                )}
                <button type="button" className="control" onClick={() => replace(back)}>
                  Leave tournament
                </button>
              </div>
              {phase !== TournamentPhase.ready && (
                <>
                  <GameStatus
                    game={state.game}
                    best={undefined}
                    celebration={session.celebration}
                  />
                  <p id="board-help" className="help">
                    Arrow keys move between cards. Enter or Space reveals a card.
                  </p>
                  <Board
                    key={session.generation}
                    ref={board}
                    game={state.game}
                    activate={controller.activate}
                  />
                </>
              )}
            </>
